pages/checkout:
---
carousel: {{theme_settings.homepage_show_carousel}}
---
{{#partial "head"}}

{{{ checkout.checkout_head }}}
{{{ stylesheet '/assets/css/optimized-checkout.css' }}}
{{ getFontsCollection }}

<script src="https://unpkg.com/axios/dist/axios.min.js"></script>
<script src="https://ajax.googleapis.com/ajax/libs/jquery/3.6.4/jquery.min.js"></script>
<script type="text/javascript" src="https://cdnjs.cloudflare.com/ajax/libs/slick-carousel/1.8.1/slick.js"></script>

<script type="text/javascript">
   window.language = {{{langJson 'optimized_checkout'}}};
</script>

{{{head.scripts}}}

{{/partial}}

{{#partial "page"}}
<header class="checkoutHeader optimizedCheckout-header bg-paint-splatter">
   <div class="checkoutHeader-content">
      <h1 class="is-srOnly">{{lang 'checkout.title'}}</h1>
      <h2 class="checkoutHeader-heading">
         <a class="checkoutHeader-link" href="{{urls.home}}">
            {{#if checkout.header_image}}
            <img alt="{{settings.store_logo.title}}" class="checkoutHeader-logo" id="logoImage"
               src="{{ checkout.header_image }}" />
            {{ else }}
            <span class="header-logo-text">{{settings.store_logo.title}}</span>
            {{/if}}
         </a>
         <div class="checkoutHeader-secure">
            <img class="checkoutHeader-icon"
               src="https://uploads-ssl.webflow.com/634d1196dfe3ee1059acb423/6449dbe4a255ae058d21a5ac_padlock%20(1)%201.png">
            <div>{{lang 'checkout.secure_checkout'}}</div>
         </div>
      </h2>
   </div>
</header>

{{{ checkout.checkout_content }}}
{{{ footer.scripts }}}

<div id="testimonialMob" class="hide">
   <section class="container testimonialCarousel">
      {{#for 1 (lang 'custom.home.testimonial-callout.number-of-callouts')}}
      <div class="slideMob">
         <blockqoute>
            <p class="h3 mobile">
               <span class="icon icon--qoute"><svg class="svg--quote" xmlns="http://www.w3.org/2000/svg"
                     viewBox="0 0 174 149" fill="none">
                     <path fill-rule="evenodd" clip-rule="evenodd"
                        d="M37.1722 79.5C36.3026 37.6509 49.4769 24.5 69 24.5L60.0005 0C16.0006 0 3.5918 30 0.00127965 79.5H0V148.5H71V79.5H37.1722Z"
                        fill="#d3d3d3" />
                     <path fill-rule="evenodd" clip-rule="evenodd"
                        d="M140.172 79.5C139.303 37.6509 152.477 24.5 172 24.5L163.001 0C119.001 0 106.592 30 103.001 79.5H103V148.5H174V79.5H140.172Z"
                        fill="#d3d3d3" />
                  </svg>
               </span>
               {{lang (concat (concat 'custom.home.testimonial-callout.callout-' $index) '.text')}}
               <cite class="mobile">{{~lang (concat (concat 'custom.home.testimonial-callout.callout-' $index)
                  '.name')~}}
                  {{#if (isString (lang (concat (concat 'custom.home.testimonial-callout.callout-' $index)
                  '.middle-bits')))}}
                  {{~lang (concat (concat 'custom.home.testimonial-callout.callout-' $index) '.middle-bits')}}
                  {{else}}
                  {{~trim ','}}
                  {{/if}}
                  <a href="{{lang (concat (concat 'custom.home.testimonial-callout.callout-' $index) '.link')}}">
                     {{~lang (concat (concat 'custom.home.testimonial-callout.callout-' $index) '.link-text')~}}
                  </a>
               </cite>
            </p>
         </blockqoute>
      </div>
      {{/for}}
   </section>
</div>

{{> components/custom/return-policy}}
{{> components/custom/customer-service}}
{{> components/custom/warranty-info}}
{{> components/page/terms-conditions addModalClass=true}}
{{> components/page/privacy-policy addModalClass=true}}
{{> components/custom/asr-details}}

<div class="modal-backgrounds"></div>
<div id="checkoutID" class="hide" data-value={{checkout.id}}></div>

{{/partial}}

{{> layout/empty}}

<script>
   (function () {
      'use strict';

      // ===========================================
      // CONFIGURATION & CONSTANTS
      // ===========================================
      const CONFIG = {
         ASR_THRESHOLD: 250,
         OBSERVER_DELAY: 300,
         SLIDE_INTERVAL: 5000,
         MOBILE_POPUP_DELAY: 10000,
         SUBTOTAL_MAX_ATTEMPTS: 50,
         SUBTOTAL_CHECK_INTERVAL: 100
      };

      // Keywords to identify pickup options (case insensitive)
      const PICKUP_KEYWORDS = ['pickup', 'pick up', 'pick-up', 'in-store', 'collect'];

      // ===========================================
      // GLOBAL STATE
      // ===========================================
      let checkoutID = document.getElementById('checkoutID').getAttribute('data-value');
      let cartItem = [];
      let itemTemplate = [];
      let subtotal = 0;
      let myInterval;

      // ===========================================
      // TEMPLATES
      // ===========================================
      const testimonialText = `<div id="testimonial" class="hide">
      <section class="container testimonialCarousel">
         {{#for 1 (lang 'custom.home.testimonial-callout.number-of-callouts')}}
         <div class="slide">
            <blockqoute>
               <p class="h3">
                  <span class="icon icon--qoute"><svg class="svg--quote" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 174 149" fill="none">
                     <path fill-rule="evenodd" clip-rule="evenodd" d="M37.1722 79.5C36.3026 37.6509 49.4769 24.5 69 24.5L60.0005 0C16.0006 0 3.5918 30 0.00127965 79.5H0V148.5H71V79.5H37.1722Z" fill="#d3d3d3"/>
                     <path fill-rule="evenodd" clip-rule="evenodd" d="M140.172 79.5C139.303 37.6509 152.477 24.5 172 24.5L163.001 0C119.001 0 106.592 30 103.001 79.5H103V148.5H174V79.5H140.172Z" fill="#d3d3d3"/></svg>
                  </span>
                  {{lang (concat (concat 'custom.home.testimonial-callout.callout-' $index) '.text')}}
                  <cite>{{~lang (concat (concat 'custom.home.testimonial-callout.callout-' $index) '.name')~}}
                     {{#if (isString (lang (concat (concat 'custom.home.testimonial-callout.callout-' $index) '.middle-bits')))}}
                        {{~lang (concat (concat 'custom.home.testimonial-callout.callout-' $index) '.middle-bits')}}
                     {{else}}
                        {{~trim ','}}
                     {{/if}}
                     <a href="{{lang (concat (concat 'custom.home.testimonial-callout.callout-' $index) '.link')}}">
                        {{~lang (concat (concat 'custom.home.testimonial-callout.callout-' $index) '.link-text')~}}
                     </a>
                  </cite>
               </p>
            </blockqoute>
         </div>
         {{/for}}
      </section>
   </div>`;

      const popupText = `{{{lang 'checkout.popup_text'}}}`;
      const popupTextMob = `{{{lang 'checkout.popup_text_mob'}}}`;

      // ===========================================
      // API FUNCTIONS
      // ===========================================
      async function getCheckout() {
         try {
            const response = await fetch('/graphql', {
               method: 'POST',
               credentials: 'same-origin',
               headers: {
                  'Content-Type': 'application/json',
                  'Authorization': 'Bearer {{ settings.storefront_api.token }}'
               },
               body: JSON.stringify({
                  query: `query getCheckout {
                  site {
                     checkout {
                        cart {
                           lineItems {
                              physicalItems {
                                 imageUrl
                                 originalPrice { value }
                                 quantity
                                 salePrice { value }
                                 name
                                 sku
                                 productEntityId
                                 variantEntityId
                                 catalogProductWithOptionSelections {
                                    prices {
                                       retailPrice { value }
                                       price { value }
                                       salePrice { value }
                                    }
                                 }
                              }
                              totalQuantity
                           }
                           amount { value }
                        }
                        grandTotal { value }
                     }
                  }
               }`
               })
            });
            return await response.json();
         } catch (error) {
            console.error('getCheckout error:', error);
            throw error;
         }
      }

      async function getProductBpn(productId, variantId) {
         const response = await fetch(`https://eomtnzhwpylu4c7.m.pipedream.net?product_id=${productId}&variant_id=${variantId}`);
         const data = await response.json();
         return data.data;
      }

      // ===========================================
      // MODAL FUNCTIONS
      // ===========================================
      function openModal(modalId) {
         const modal = document.querySelector(modalId);
         const backgrounds = document.querySelector('.modal-backgrounds');
         if (modal) modal.classList.add('open');
         if (backgrounds) backgrounds.classList.add('has-activeModal');
      }

      function closeAllModals() {
         document.querySelectorAll('.modal').forEach(modal => modal.classList.remove('open'));
         document.querySelector('.modal-backgrounds')?.classList.remove('has-activeModal');
      }

      function initModalCloseButtons() {
         document.querySelectorAll('.modal-close').forEach(btn => {
            btn.addEventListener('click', closeAllModals);
         });
      }

      function closeModal() {
         $('.modal-backgrounds.has-activeModal').not('.modal.open').click(function () {
            $('.modal.open').removeClass('open');
            $(this).removeClass('has-activeModal');
         });
      }

      // ===========================================
      // CART & PRODUCT DISPLAY FUNCTIONS
      // ===========================================
      function generateItemTemplate(item, originalPrice, salePrice, mpnHtml) {
         const baseTemplate = `
         <li class="productList-item is-visible a">
            <div class="product" data-test="cart-item">
               <figure class="product-column product-figure">
                  <img alt="${item.name}" data-test="cart-item-image" src="${item.imageUrl}">
               </figure>
               <div class="product-column product-body" data-productentityid="${item.productEntityId}">
                  <h4 class="product-title optimizedCheckout-contentPrimary" data-test="cart-item-product-title">
                     ${item.quantity} x ${item.name}
                  </h4>
                  ${mpnHtml}
               </div>
               <div class="product-column product-actions">`;

         if (originalPrice === salePrice) {
            return baseTemplate + `
                  <div class="product-price optimizedCheckout-contentPrimary" data-test="cart-item-product-price">
                     $${originalPrice.toLocaleString()}
                  </div>
               </div>
            </div>
         </li>`;
         } else {
            return baseTemplate + `
                  <div class="product-price original optimizedCheckout-contentPrimary">
                     $${originalPrice.toLocaleString()}
                  </div>
                  <div class="product-price discounted optimizedCheckout-contentPrimary">
                     $${salePrice.toLocaleString()}
                  </div>
               </div>
            </div>
         </li>`;
         }
      }

      function updateSubtotal(total) {
         let attempts = 0;
         const updateInterval = setInterval(() => {
            const element = $('[data-test="cart-subtotal"] .cart-priceItem-value span');
            if (element.length > 0) {
               element.text(`$${total.toLocaleString()}`);
               clearInterval(updateInterval);
            } else {
               attempts++;
               if (attempts >= CONFIG.SUBTOTAL_MAX_ATTEMPTS) {
                  clearInterval(updateInterval);
                  console.error('Failed to find subtotal element');
               }
            }
         }, CONFIG.SUBTOTAL_CHECK_INTERVAL);
      }

      function renderCartItems() {
         const productList = document.querySelector('.productList');
         if (!productList) return;

         document.querySelectorAll('.productList-item').forEach(item => item.remove());
         itemTemplate.forEach(template => {
            productList.innerHTML += template;
         });
      }

      function listenEvent() {
         const cartDrawer = document.querySelector('.cartDrawer');
         if (cartDrawer) {
            cartDrawer.addEventListener('click', () => {
               setTimeout(renderCartItems, 500);
            });
         }
      }

      // ===========================================
      // CHECKOUT UI FUNCTIONS
      // ===========================================
      function appendTextPolicy() {
         if ($('.checkout-step--payment .form-actions .accept-tnc--text').length === 0) {
            const formActions = document.querySelector('.checkout-step--payment .form-actions');
            if (formActions) {
               formActions.insertAdjacentHTML('beforeend', `{{{lang 'checkout.confirmation_text'}}}`);
               document.querySelector('#modal-tnc')?.addEventListener('click', () => openModal('#modal-terms-conditions'));
               document.querySelector('#modal-policy')?.addEventListener('click', () => openModal('#modal-privacy-policy'));
            }
         }
      }

      function appendTextCoupon() {
         if ($('.coupon-text-append').length === 0) {
            if ($('.form-prefixPostfix').length) {
               $('.form-prefixPostfix').parent().append(`{{{lang 'checkout.coupon_text'}}}`);
            }
            if ($('.form-fieldset.redeemable-entry').length) {
               $('.form-fieldset.redeemable-entry').parent().append(`{{{lang 'checkout.coupon_text'}}}`);
            }
         }
      }

      function waitForCheckoutViewContent() {
         const formActionsElement = document.querySelector('.checkout-view-content .form-actions');
         if (formActionsElement && formActionsElement.offsetWidth > 0 && formActionsElement.offsetHeight > 0) {
            const targetElement = document.querySelector('.checkout-step--payment .form-actions');
            if (targetElement && targetElement.offsetWidth > 0 && targetElement.offsetHeight > 0) {
               appendTextPolicy();
            } else {
               setTimeout(waitForCheckoutViewContent, 500);
            }
         } else {
            setTimeout(waitForCheckoutViewContent, 500);
         }
      }

      // ===========================================
      // TESTIMONIAL CAROUSEL FUNCTIONS
      // ===========================================
      function initDesktopCarousel() {
         const slides = document.querySelectorAll('.slide');
         if (slides.length === 0) return null;

         let currentSlide = 0;
         return setInterval(() => {
            slides[currentSlide].className = 'slide';
            currentSlide = (currentSlide + 1) % slides.length;
            slides[currentSlide].className = 'slide showing';
         }, CONFIG.SLIDE_INTERVAL);
      }

      function initMobileCarousel() {
         const slides = document.querySelectorAll('.slideMob');
         if (slides.length === 0) return null;

         let currentSlide = 0;
         return setInterval(() => {
            slides[currentSlide].className = 'slideMob';
            currentSlide = (currentSlide + 1) % slides.length;
            slides[currentSlide].className = 'slideMob showing';
         }, CONFIG.SLIDE_INTERVAL);
      }

      // ===========================================
      // POPUP & TESTIMONIAL SETUP
      // ===========================================
      function setupDesktopPopup() {
         if ($('.checkout-popup').length >= 2) return;

         const nodecheckout = document.createElement('div');
         nodecheckout.classList.add('checkout-popup');
         nodecheckout.innerHTML = popupText;

         const testimonial = document.querySelector('#testimonial');
         const layoutCart = document.querySelector('.layout-cart');

         if (layoutCart && testimonial) {
            testimonial.classList.remove('hide');
            layoutCart.appendChild(nodecheckout);
            layoutCart.appendChild(testimonial);

            document.querySelector('#return-policy')?.addEventListener('click', () => openModal('#modal-return-policy'));
            document.querySelector('#customer-service')?.addEventListener('click', () => openModal('#modal-customer-service'));
            document.querySelector('#warranties')?.addEventListener('click', () => openModal('#modal-warranties'));
            initModalCloseButtons();
         }
      }

      function setupMobilePopup() {
         const markerDiv = document.createElement('div');
         markerDiv.innerHTML = popupTextMob;

         const testimonialMob = document.querySelector('#testimonialMob');
         const layoutMain = document.querySelector('.layout-main');

         if (layoutMain && testimonialMob) {
            testimonialMob.classList.remove('hide');
            layoutMain.appendChild(markerDiv.firstChild);
            layoutMain.appendChild(testimonialMob);

            document.querySelector('#return-policy-mob')?.addEventListener('click', () => openModal('#modal-return-policy'));
            document.querySelector('#customer-service-mob')?.addEventListener('click', () => openModal('#modal-customer-service'));
            document.querySelector('#warranties-mob')?.addEventListener('click', () => openModal('#modal-warranties'));
            initModalCloseButtons();
         }
      }

      // ===========================================
      // MAIN GREETING FUNCTION (Cart Display)
      // ===========================================
      function myGreeting() {
         const itemList = document.querySelectorAll('.productList-item');
         if (itemList.length > 0) {
            clearInterval(myInterval);
            listenEvent();
            itemList.forEach(item => item.remove());
         }

         renderCartItems();
         setupDesktopPopup();

         const checkoutApp = document.getElementById('checkout-app');
         if (checkoutApp) {
            checkoutApp.addEventListener('click', handleCheckoutAppClick);
         }
      }

      function handleCheckoutAppClick() {
         // Handle policy text
         if ($('.form-actions').length > 0 && $('.accept-tnc--text').length === 0) {
            const checkAndInsert = () => {
               const formActionsElement = document.querySelector('.checkout-step--payment .form-actions');
               if (formActionsElement) {
                  appendTextPolicy();
               } else {
                  setTimeout(checkAndInsert, 500);
               }
            };
            checkAndInsert();
         }

         // Re-render cart items if needed
         if ($('.productList-item.is-visible.a').length === 0) {
            renderCartItems();
         }

         // Handle modal backgrounds
         if ($('.modal-backgrounds.has-activeModal').not('.modal.open').length !== 0) {
            closeModal();
         }
      }

      // ===========================================
      // ASR FIELD FUNCTIONS
      // ===========================================
      function handleASRField() {
         const asrField = $('#checkoutShippingAddress .dynamic-form-field.dynamic-form-field--field_34');
         if (!asrField.length) return;

         getCheckout().then(data => {
            const priceNumber = data?.data?.site?.checkout?.grandTotal?.value || 0;

            if (priceNumber >= CONFIG.ASR_THRESHOLD) {
               asrField.show();

               const checkboxYes = document.querySelector('#checkoutShippingAddress #field_34Input-0');
               const checkboxNo = document.querySelector('#checkoutShippingAddress #field_34Input-1');

               if (!checkboxYes || !checkboxNo) return;

               // Auto-select "Yes" only if neither option is selected
               if (!checkboxYes.checked && !checkboxNo.checked) {
                  checkboxYes.click();
               }

               // Add "Full details" link only once
               if ($('label[for="field_34Input-1"]').find('#asr-details').length === 0) {
                  $('label[for="field_34Input-1"]').append(
                     $('<a>', {
                        id: 'asr-details',
                        text: 'Full details',
                        class: 'popup-textspan',
                        css: { marginLeft: '5px' }
                     })
                  );

                  document.querySelector('#asr-details')?.addEventListener('click', () => openModal('#modal-asr-details'));
               }
            } else {
               asrField.hide();
               $('#field_34Input-0, #field_34Input-1').prop('checked', false);
            }
         });
      }

      // ===========================================
      // SHIPPING OPTIONS FUNCTIONS
      // ===========================================

      // Check if text contains any pickup keywords
      function isPickupOption(text) {
         if (!text) return false;
         const lowerText = text.toLowerCase();
         return PICKUP_KEYWORDS.some(keyword => lowerText.includes(keyword));
      }

      // Get the label text for a shipping radio button
      function getShippingOptionLabel($radio) {
         const $container = $radio.closest('li, .form-checklist-item, .shippingOption');
         let labelText = '';

         const $label = $container.find('label, .shippingOption-desc, .form-label');
         if ($label.length) {
            labelText = $label.text();
         }

         if (!labelText) {
            labelText = $container.text();
         }

         return labelText;
      }

      // Hide pickup button but always show unavailable message
      function handlePickupOptions() {
         const $allShippingOptions = $('input[name="shippingOptionIds"], input[name^="shippingOptionIds"]');
         let hadPickupSelected = false;

         $allShippingOptions.each(function () {
            const $radio = $(this);
            const $container = $radio.closest('li, .form-checklist-item, .shippingOption');
            const labelText = getShippingOptionLabel($radio);

            if (isPickupOption(labelText)) {
               // Check if pickup was selected before hiding
               if ($radio.is(':checked')) {
                  hadPickupSelected = true;
                  $radio.prop('checked', false);
               }

               // Skip if already processed
               if ($container.hasClass('pickup-processed')) return;
               $container.addClass('pickup-processed');

               // Disable radio button and add styling
               $radio.prop('disabled', true);
               $container.addClass('pickup-unavailable');

               // Add unavailable message inside the label
               const $label = $container.find('label').first();
               if ($label.length && $label.find('.pickup-unavailable-message').length === 0) {
                  $label.append(
                     '<div class="pickup-unavailable-message">This option is currently unavailable</div>'
                  );
               }

               // Hide the entire container (button + message together)
               $container.hide();
            }
         });

         // Show top notice only if user had pickup pre-selected
         if (hadPickupSelected) {
            showPickupUnavailableMessage();
         }
      }

      // Show message at top of shipping section
      function showPickupUnavailableMessage() {
         // Don't add duplicate messages
         if ($('.pickup-unavailable-notice').length > 0) return;

         const $shippingSection = $('.checkout-step--shipping .checkout-view-content, .checkout-step--shipping form, #checkoutShippingAddress').first();

         if ($shippingSection.length) {
            $shippingSection.prepend(
               '<div class="pickup-unavailable-notice">Pickup option is currently unavailable. Please select a different shipping method.</div>'
            );
         }
      }

      // Block clicks on pickup options and setup click interception
      function setupPickupBlocker() {
         // Intercept clicks on shipping radio buttons
         $(document).on('click', 'input[name="shippingOptionIds"], input[name^="shippingOptionIds"]', function (e) {
            const $radio = $(this);
            const labelText = getShippingOptionLabel($radio);

            if (isPickupOption(labelText)) {
               e.preventDefault();
               e.stopPropagation();
               e.stopImmediatePropagation();
               $radio.prop('checked', false);
               return false;
            }
         });

         // Also intercept clicks on labels
         $(document).on('click', '.form-checklist-item label, .shippingOption label', function (e) {
            const $container = $(this).closest('li, .form-checklist-item, .shippingOption');
            const $radio = $container.find('input[type="radio"]');
            const labelText = getShippingOptionLabel($radio);

            if (isPickupOption(labelText)) {
               e.preventDefault();
               e.stopPropagation();
               e.stopImmediatePropagation();
               $radio.prop('checked', false);
               return false;
            }
         });

         // Periodic check: If pickup is somehow selected (DOM manipulation), deselect it
         setInterval(() => {
            const $selectedShipping = $('input[name="shippingOptionIds"]:checked, input[name^="shippingOptionIds"]:checked');
            if ($selectedShipping.length) {
               const labelText = getShippingOptionLabel($selectedShipping);
               if (isPickupOption(labelText)) {
                  $selectedShipping.prop('checked', false);
                  showPickupUnavailableMessage();
               }
            }
         }, 500);
      }

      // Run on DOM changes to handle pickup options
      function handleShippingOptions() {
         handlePickupOptions();
      }

      // ===========================================
      // MUTATION OBSERVERS
      // ===========================================
      const asrObserver = new MutationObserver(() => {
         setTimeout(handleASRField, CONFIG.OBSERVER_DELAY);
      });

      const shipObserver = new MutationObserver(() => {
         setTimeout(handleShippingOptions, CONFIG.OBSERVER_DELAY);
      });

      // ===========================================
      // INITIALIZATION
      // ===========================================
      async function initCheckout() {
         try {
            const data = await getCheckout();
            cartItem = data.data.site.checkout.cart.lineItems.physicalItems;
            subtotal = 0;

            for (let i = 0; i < cartItem.length; i++) {
               const item = cartItem[i];
               const priceOption = item.catalogProductWithOptionSelections;

               let originalPrice, salePrice;
               if (priceOption) {
                  originalPrice = priceOption.prices.retailPrice.value * item.quantity;
                  salePrice = item.salePrice.value * item.quantity;
               } else {
                  originalPrice = item.originalPrice.value * item.quantity;
                  salePrice = item.salePrice.value * item.quantity;
               }

               subtotal += originalPrice > 0 ? originalPrice : salePrice;

               let mpnHtml = '';
               if (item.productEntityId === 2952) {
                  try {
                     const bpnData = await getProductBpn(item.productEntityId, item.variantEntityId);
                     const bpn = bpnData?.bin_picking_number || null;
                     if (bpn) {
                        mpnHtml = `<h4 class="product-title optimizedCheckout-contentPrimary">Set Contents: ${bpn}</h4>`;
                     }
                  } catch (e) {
                     console.error('Error fetching BPN:', e);
                  }
               }

               itemTemplate[i] = generateItemTemplate(item, originalPrice, salePrice, mpnHtml);
            }

            updateSubtotal(subtotal);

            myInterval = setInterval(myGreeting, 500);
         } catch (error) {
            console.error('Checkout initialization error:', error);
         }
      }

      function init() {
         // Append testimonial template to body
         $('body').append(testimonialText);

         // Start waiting for checkout content
         waitForCheckoutViewContent();

         // Initialize carousels
         initDesktopCarousel();
         initMobileCarousel();

         // Setup mobile popup after delay
         setTimeout(setupMobilePopup, CONFIG.MOBILE_POPUP_DELAY);

         // Initialize checkout
         initCheckout();

         // Start observers
         asrObserver.observe(document.body, { childList: true, subtree: true });
         shipObserver.observe(document.body, { childList: true, subtree: true });

         // Setup pickup blocker - intercepts clicks on pickup options
         setupPickupBlocker();

         // Event listeners
